poles = [FreeCAD.Vector(0, 12, 0), FreeCAD.Vector(10, 6, 0)]

# Build from poles first
bspline.buildFromPoles(poles)
print(f"After buildFromPoles: NbPoles={bspline.NbPoles}, isRational={bspline.isRational()}")

# Check if we can set weights
