    try:
        bspline.setWeight(0, 1.0)
        print("setWeight(0, 1.0) succeeded")
    except Exception as e:
        print(f"setWeight failed: {e}")

# Check getWeights
if hasattr(bspline, 'getWeights'):
    try:
        weights = bspline.getWeights()
        print(f"Weights: {weights}")
    except Exception as e:
        print(f"getWeights failed: {e}")

# Check getPolesAndWeights
